    const cv = argVals(args[0])
    const e = cv.find((v) => v.k === 'e')
    if (e) return e
    if (cv.length !== 1) return err('#VALUE!')
    const c = cv[0]
    let t
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    const vs = argVals(args[t ? 1 : 2])
    return vs.find((v) => v.k === 'e') || (vs.length === 1 ? vs[0] : err('#VALUE!'))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const vs = argVals(args[0])
    const e = vs.find((v) => v.k === 'e')
    if (e) return e
    if (vs.length !== 1) return err('#VALUE!')
    const x = toNum(vs[0])
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) vals.push(...argVals(a))
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const xs = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    xs.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(xs.reduce((s, x) => s + x, 0))
    case 'MIN': return fin(Math.min(...xs))
    case 'MAX': return fin(Math.max(...xs))
    case 'AVG': return fin(xs.reduce((s, x) => s + x, 0) / xs.length)
  }
  return err('#ERR!')
