  const name = cell.addr.key
  if (mode[0] === 'deps') {
    const set = new Map()
    if (cell.parsed) collectDeps(cell.parsed.e, set)
    const list = [...set.values()].sort(cmpAddr)
    out.push(`${name}:` + list.map((a) => ' ' + a.key).join(''))
  } else {
    const v = cellValue(cell.addr)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${name}=${s}`)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

