      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l)
      if (l.k === 'e') return l
      const r = ev(n.r)
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(n)
  }
  return err('#ERR!')
}

function call(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const cv = argVals(args[0])
    const e = cv.find((v) => v.k === 'e')
    if (e) return e
    if (cv.length !== 1) return err('#VALUE!')
    const c = cv[0]
    let t
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    const vs = argVals(args[t ? 1 : 2])
    return vs.find((v) => v.k === 'e') || (vs.length === 1 ? vs[0] : err('#VALUE!'))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const vs = argVals(args[0])
    const e = vs.find((v) => v.k === 'e')
    if (e) return e
    if (vs.length !== 1) return err('#VALUE!')
    const x = toNum(vs[0])
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) vals.push(...argVals(a))
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const xs = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    xs.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(xs.reduce((s, x) => s + x, 0))
    case 'MIN': return fin(Math.min(...xs))
    case 'MAX': return fin(Math.max(...xs))
    case 'AVG': return fin(xs.reduce((s, x) => s + x, 0) / xs.length)
  }
  return err('#ERR!')
}

// ---- output
const out = []
for (const cell of ordered) {
  const name = cell.addr.key
  if (mode[0] === 'deps') {
    const set = new Map()
    if (cell.parsed) collectDeps(cell.parsed.e, set)
    const list = [...set.values()].sort(cmpAddr)
    out.push(`${name}:` + list.map((a) => ' ' + a.key).join(''))
  } else {
    const v = cellValue(cell.addr)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${name}=${s}`)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
